import time
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

# Configuration constants
I2C_ADDRESS = 0x3C
DISPLAY_REFRESH_INTERVAL = 2  # seconds


def initialize_display():
    """Initialize the OLED display."""
    try:
        serial_interface = i2c(port=1, address=I2C_ADDRESS)
        oled_device = ssd1306(serial_interface)
        return oled_device
    except Exception as e:
        print(f"Error initializing display: {e}")
        return None


def validate_temperature(temperature_value):
    """Validate the temperature reading."""
    return -40 <= temperature_value <= 85


def update_display(oled_device, temperature_value):
    """Update the OLED display with the given temperature."""
    try:
        with canvas(oled_device) as draw:
            draw.text((0, 0), f"Temp: {temperature_value:.1f} C", fill="white")
    except Exception as e:
        print(f"Error updating display: {e}")


def main():
    """Main function to read and display simulated temperature data."""
    oled = initialize_display()

    if oled is None:
        exit(1)

    try:
        while True:
            # Simulate sensor reading
            current_temperature = 27.5  # Example temperature in Celsius

            if validate_temperature(current_temperature):
                update_display(oled, current_temperature)
                print(f"Displaying temperature: {current_temperature:.1f} C")
            else:
                print("Invalid temperature reading.")

            time.sleep(DISPLAY_REFRESH_INTERVAL)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # Cleanup resources
        print("Cleaning up resources...")
        if oled:
            oled.clear()


if __name__ == "__main__":
    main()

import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration constants
I2C_ADDRESS = 0x48  # Default I2C address of the ADS1115
SAMPLE_INTERVAL_SECONDS = 0.1  # Time between sensor readings


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_adc(i2c_bus):
    """Initialize the ADS1115 ADC."""
    try:
        return ADS.ADS1115(i2c_bus)
    except Exception as e:
        print(f"Error initializing ADS1115: {e}")
        return None


def create_analog_channel(adc_device, channel_number=0):
    """Create an analog input channel on the ADC."""
    try:
        return AnalogIn(adc_device, channel_number)
    except Exception as e:
        print(f"Error creating analog input channel: {e}")
        return None


def read_sensor_value(channel_object):
    """Read the raw value from the specified analog channel."""
    try:
        return channel_object.value
    except Exception as e:
        print(f"Error reading sensor value: {e}")
        return None


def validate_reading(reading_value):
    """Validate that the reading is within a reasonable range."""
    return 0 <= reading_value <= 65535


def main():
    """Main function to continuously sample and print sensor data."""

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    adc_device = initialize_adc(i2c_bus)
    if adc_device is None:
        return  # Exit if ADC initialization failed

    analog_channel = create_analog_channel(adc_device)
    if analog_channel is None:
        return  # Exit if channel creation failed

    try:
        while True:
            sensor_value = read_sensor_value(analog_channel)

            if sensor_value is not None and validate_reading(sensor_value):
                print(f"Sensor Reading: {sensor_value}")

            time.sleep(SAMPLE_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        # No specific cleanup needed for I2C or ADS1115 with this library,
        # but included for potential future expansion.
        print("Exiting program.")


if __name__ == "__main__":
    main()

