import time
import logging
import threading

# Logging configuration for the hydroponics control station
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

SERIAL_PORT = "/dev/ttyS0"
BAUD_RATE = 9600


class SerialCommunicator:
    """Handles UART communication between the Raspberry Pi and a sensor node."""

    def __init__(self, port_name, baud):
        # Store the serial port name and baud rate
        self.port_name = port_name
        self.baud = baud
        self.serial_handle = None
        self.running_flag = True

    def open_port(self):
        """Open the serial port and prepare for reading."""
        import serial
        try:
            # Open the UART serial port
            self.serial_handle = serial.Serial(port=self.port_name, baudrate=self.baud, timeout=1)
        except serial.SerialException as error:
            logging.error("Could not open serial port: %s", error)
            self.serial_handle = None

    def read_and_process(self):
        """Continuously read one line from the serial port and log it."""
        while self.running_flag and self.serial_handle is not None:
            try:
                raw_line = self.serial_handle.readline()
                decoded_text = raw_line.decode("utf-8").strip()
                if decoded_text:
                    logging.info("Received: %s", decoded_text)
            except Exception as read_error:
                logging.warning("Read error: %s", read_error)
            time.sleep(0.5)

    def start_reading(self):
        """Start the background thread that reads the serial port."""
        self.open_port()
        if self.serial_handle is None:
            return
        self.reading_thread = threading.Thread(target=self.read_and_process)
        self.reading_thread.daemon = True
        self.reading_thread.start()

    def stop_reading(self):
        """Signal the reader thread to stop and close the port."""
        self.running_flag = False
        if self.serial_handle is not None:
            self.serial_handle.close()


if __name__ == "__main__":
    communicator = SerialCommunicator(SERIAL_PORT, BAUD_RATE)
    try:
        # Start listening for sensor readings
        communicator.start_reading()
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Stopping serial reader")
    finally:
        # Stop the thread and clean up the serial port
        communicator.stop_reading()

