        raw_value = read_adc_channel(channel_index)
        if validate_reading(raw_value):
            print(f"ADC Channel {channel_index}: {raw_value}")
        else:
            print(f"Invalid reading from channel {channel_index}. Value: {raw_value}")
    except Exception as error:
        print(f"Error processing channel {channel_index}: {error}")

