import time
from gpiozero.pins.pca9685 import PCA9685Factory
from Adafruit_PCA9685 import Adafruit_PCA9685

def create_pca9685(pin_factory=None):
    """Creates a PCA9685 driver instance."""
    if pin_factory == 'soft':
        return PCA9685Factory()
    elif pin_factory == 'hard':
        return Adafruit_PCA9685.HardwarePWM(0)
    else:
        raise ValueError("Invalid pin_factory: must be 'soft', 'hard', or None")

def set_channel_value(driver, channel, value):
    """Sets the PWM value for a specific channel."""
    if isinstance(driver, PCA9685Factory):
        driver.pin(channel).value = max(min(value, 1), -1)  # Clamp value to [-1, 1]
    elif isinstance(driver, Adafruit_PCA9685.HardwarePWM):
        driver.set_pwm(channel, 0, int(value * 4096 / 2))  # Adjust for 12-bit resolution

def get_channel_value(driver, channel):
    """Gets the current PWM value for a specific channel."""
    if isinstance(driver, PCA9685Factory):
        return driver.pin(channel).value
    elif isinstance(driver, Adafruit_PCA9685.HardwarePWM):
        return driver.get_pwm(channel, 0)

def main():
    """Main function to control and report motor controller outputs."""
    try:
        pca9685 = create_pca9685()  # Create PCA9685 driver
        pwm = Adafruit_PCA9685.Adafruit_PCA9685() # Direct PCA9685 object for get_pwm
        pwm.set_pwm_freq(50) 
        print('Setting PWM frequency to 50 Hz')

        while True:
            try:
                for i in range(16):
                    value = float(input(f"Motor {i}: "))
                    set_channel_value(pca9685, i, value)
                    print(f"Channel {i} -> {get_channel_value(pca9685, i)} (Input: {value})")
            except ValueError as e:
                print(f"Error: Invalid input. Please enter a number. {e}")
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

    except KeyboardInterrupt:
        print('Exiting...')
    finally:
        pca9685.close()

if __name__ == "__main__":
    main()

