import time
import board
import busio
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration constants
I2C_ADDRESS = 0x48  # Default I2C address of the ADS1015
SAMPLE_INTERVAL_SECONDS = 1  # Time between sensor readings


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_adc(i2c_bus):
    """Initialize the ADS1015 ADC."""
    try:
        return ADS.ADS1015(i2c_bus, address=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None


def create_analog_channel(adc_device, channel_number):
    """Create an analog input channel on the ADC."""
    try:
        return AnalogIn(adc_device, channel_number)
    except Exception as e:
        print(f"Error creating analog channel: {e}")
        return None


def read_sensor_value(channel_object):
    """Read the raw value from the specified analog channel."""
    try:
        return channel_object.value
    except Exception as e:
        print(f"Error reading sensor value: {e}")
        return None


def validate_reading(reading_value):
    """Validate that the reading is within a reasonable range."""
    return reading_value is not None and 0 <= reading_value <= 65535


def display_reading(reading_value):
    """Print the sensor reading to the console."""
    print(f"Sensor Reading: {reading_value}")


def main():
    """Main function to continuously sample and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return 1  # Indicate initialization failure

    adc_device = initialize_adc(i2c_bus)
    if adc_device is None:
        return 1

    sensor_channel = create_analog_channel(adc_device, ADS.P_0)  # Read from channel 0
    if sensor_channel is None:
        return 1

    try:
        while True:
            sensor_value = read_sensor_value(sensor_channel)

            if validate_reading(sensor_value):
                display_reading(sensor_value)
            else:
                print("Invalid sensor reading.")

            time.sleep(SAMPLE_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nExiting program.")
        return 0  # Normal exit

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return 1  # Error exit

    finally:
        # No specific cleanup needed for I2C or ADS1015 in this library,
        # but included for potential future expansion.
        pass


if __name__ == "__main__":
    exit_code = main()
    exit(exit_code)

