import time
import serial

# UART configuration for the environmental sensor module
SERIAL_PORT = "/dev/ttyS0"
BAUD_RATE = 9600


def read_environmental_data(serial_connection):
    """Read one line of comma-separated data from the serial port."""
    # Strip whitespace and split into components
    raw_line = serial_connection.readline().decode("utf-8", "ignore").strip()
    if not raw_line:
        return None
    try:
        temperature_value, humidity_value = raw_line.split(",")
        return float(temperature_value), float(humidity_value)
    except ValueError:
        return None


def validate_reading(temperature_value, humidity_value):
    """Check whether both readings are plausible environmental values."""
    # Temperature in Celsius, humidity percentage
    return -40 <= temperature_value <= 85 and 0 <= humidity_value <= 100


if __name__ == "__main__":
    # Open the serial connection to the sensor
    serial_connection = None
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        while True:
            reading = read_environmental_data(serial_connection)
            if reading is not None:
                temperature_value, humidity_value = reading
                if validate_reading(temperature_value, humidity_value):
                    print("Temperature: {:.1f}C Humidity: {:.1f}%".format(
                        temperature_value, humidity_value))
            else:
                print("No valid reading received")
            time.sleep(1)
    except serial.SerialException as serial_error:
        # Report any failure to open or communicate over the serial port
        print("Serial communication failed:", serial_error)
        exit(1)
    except KeyboardInterrupt:
        # Allow graceful shutdown when interrupted by the user
        print("Exiting")
    finally:
        # Always close the serial port to free the resource
        if serial_connection is not None:
            serial_connection.close()

import time
