import sys

# Constants for graceful shutdown handling
SHUTDOWN_SIGNAL = signal.SIGINT
DEFAULT_HANDLING_SECONDS = 3


def register_shutdown_handler(termination_seconds=DEFAULT_HANDLING_SECONDS):
    """Registers a signal handler for graceful shutdown."""

    def signal_handler(signum, frame):
        print("Shutting down...")
        sys.exit(0)

    signal.signal(SHUTDOWN_SIGNAL, signal_handler)


class CameraController:
    """Controls the Raspberry Pi camera to capture images."""

    def __init__(self):
        self.camera_device = None

    def initialize_camera(self):
        """Initializes the camera."""
        try:
