    """

    def __init__(self, config):
        """
        Initializes the GPIOZeroController with pin configurations.

        Args:
            config (dict): A dictionary containing pin assignments and other settings.
        """
        self.config = config
        self.led_objects = {}  # Store LED objects for potential future use (e.g., dimming)

        # Create LED objects based on pin configuration
        for pin_name, pin_config in self.config['pin_assignments'].items():
            try:
                if pin_config.get('type') == 'output':
                    led_class = led_pins.get(pin_config['pin_number'])
                    if led_class:
                        self.led_objects[pin_name] = led_class(pin_config['pin_number'], initial_value=0) # Initialize all LEDs to off
                        print(f"Created {pin_config['type']} on {pin_name} (GPIO {pin_config['pin_number']})")
                    else:
                         print(f"Warning: No class defined for output pin {pin_config['pin_number']}")

                elif pin_config.get('type') == 'input':
                     led_class = led_pins.get(pin_config['pin_number'])
                     if led_class:
                        setattr(self, pin_name, led_class(pin_config['pin_number']))
                        print(f"Created {pin_config['type']} on {pin_name} (GPIO {pin_config['pin_number']})")
                     else:
                         print(f"Warning: No class defined for input pin {pin_config['pin_number']}")

            except Exception as e:
