        Args:
            led_name (str): The name of the LED (e.g., "LED_System").
            brightness (float): The desired brightness level (0.0 to 1.0).
        """
        try:
            if 0 <= brightness <= 1:
                self.led_objects[led_name].value = brightness
                print(f"{led_name} set to {brightness}")
            else:
                print(f"Invalid brightness value: {brightness}. Must be between 0 and 1.")
        except KeyError:
            print(f"Error: LED named '{led_name}' not found in configured pins.")
        except Exception as e:
            print(f"Error setting {led_name} brightness: {e}")

