        print(f"Error reading ADC channel {channel}: {e}")
        return None


def validate_reading(reading_value):
    """Validate that the reading is within the acceptable range."""
    return reading_value is not None and 0 <= reading_value <= 1023


def process_reading(reading_value):
    """Print the processed ADC reading to standard output."""
    print(f"ADC Channel Value: {reading_value}")


def main():
    """Main function to sample and process ADC readings."""
    adc = initialize_adc()

    try:
        for _ in range(NUM_SAMPLES):
            raw_value = read_adc_channel(adc, ADC_CHANNEL)

            if validate_reading(raw_value):
                process_reading(raw_value)
            else:
                print("Invalid ADC reading received.")

            time.sleep(SAMPLE_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
