    """Reads temperature and humidity from the DHT sensor."""
    try:
        temperature_c = sensor_instance.temperature
        humidity_percent = sensor_instance.humidity
        return temperature_c, humidity_percent
    except RuntimeError as error:
        print(f"Sensor read error: {error}")
        return None, None


def validate_data(temperature, humidity):
    """Validates temperature and humidity readings."""
    if temperature is not None and (temperature < -40 or temperature > 80):
        print("Error: Invalid temperature reading.")
        return False
    if humidity is not None and (humidity < 0 or humidity > 100):
        print("Error: Invalid humidity reading.")
        return False
    return True


def display_readings(temperature, humidity):
    """Prints the temperature and humidity to the console."""
    if temperature is not None and humidity is not None:
        print(f"Temperature: {temperature:.1f} C, Humidity: {humidity:.1f} %")


def main():
    """Main function to read and process DHT22 sensor data."""
    try:
        sensor = initialize_sensor(DHT_PIN)
        for _ in range(NUM_SAMPLES):
            temperature, humidity = read_sensor_data(sensor)
            if validate_data(temperature, humidity):
                display_readings(temperature, humidity)
            else:
