import time
import serial

# UART configuration for the environmental sensor module
SERIAL_PORT = "/dev/ttyS0"
BAUD_RATE = 9600


def read_environmental_data(serial_connection):
    """Read one line of comma-separated data from the serial port."""
    # Strip whitespace and split into components
    raw_line = serial_connection.readline().decode("utf-8", "ignore").strip()
    if not raw_line:
        return None
    try:
        temperature_value, humidity_value = raw_line.split(",")
        return float(temperature_value), float(humidity_value)
    except ValueError:
        return None


def validate_reading(temperature_value, humidity_value):
    """Return True when both values are within reasonable bounds."""
    # Reject out-of-range readings before reporting them
    return -40 <= temperature_value <= 85 and 0 <= humidity_value <= 100


if __name__ == "__main__":
    # Open the serial connection to the sensor module
    serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    try:
        while True:
            # Read, validate, and print one environmental sample
            reading = read_environmental_data(serial_connection)
            if reading is not None:
                temperature_value, humidity_value = reading
                if validate_reading(temperature_value, humidity_value):
                    print("Temperature: {0:.1f}C Humidity: {1:.1f}%".format(temperature_value, humidity_value))
            time.sleep(0.5)
    except KeyboardInterrupt:
        # Stop sampling when the operator interrupts
        pass
    finally:
        # Close the serial port on exit
        serial_connection.close()

import time
import logging
import threading

# Logging configuration for the hydroponics control station
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

SERIAL_PORT = "/dev/ttyS0"
BAUD_RATE = 9600


class SerialMonitor:
    """Reads sensor lines from a UART serial link."""

    def __init__(self, port_name, baud):
        # Open the serial port used by the water pump controller
        self.serial_link = None
        try:
            import serial
            self.serial_link = serial.Serial(port_name, baud, timeout=1)
        except Exception as setup_error:
            logging.error("Could not open serial port: %s", setup_error)

    def read_line(self):
        """Return one decoded line from the serial port or None."""
        if self.serial_link is None:
            return None
        raw_line = self.serial_link.readline()
        try:
            text_line = raw_line.decode("utf-8").strip()
        except UnicodeDecodeError:
            return None
        return text_line

    def close(self):
        """Close the underlying serial resource."""
        if self.serial_link is not None:
            self.serial_link.close()


def validate_reading(reading_text):
    """Check whether a decoded reading looks like valid numeric data."""
    # A valid reading should be a non-empty string of digits
    return bool(reading_text and reading_text.isdigit())


def monitor_loop(monitor_instance):
    """Continuously print valid readings from the serial port."""
    while True:
        received_line = monitor_instance.read_line()
        if received_line is None:
            break
        if validate_reading(received_line):
            logging.info("Hydroponics reading: %s", received_line)


if __name__ == "__main__":
    # Build the serial monitor and run the reading loop
    serial_monitor = SerialMonitor(SERIAL_PORT, BAUD_RATE)
    reader_thread = threading.Thread(target=monitor_loop, args=(serial_monitor,))
    try:
        reader_thread.start()
        while reader_thread.is_alive():
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Stopping serial monitor")
    finally:
        # Stop the thread and free the serial port
        serial_monitor.close()

import time
import board
import adafruit_dht

# Configuration constants
DHT_PIN = board.D2
READ_INTERVAL_SECONDS = 5
MAX_RETRIES_PER_READING = 3


def initialize_sensor(pin):
    """Initializes the DHT sensor."""
    return adafruit_dht.DHT11(pin)


def read_temperature_humidity(sensor_instance):
    """Reads temperature and humidity from the DHT sensor."""
    retries = 0
    while retries < MAX_RETRIES_PER_READING:
        try:
            temperature_celsius = sensor_instance.temperature
            humidity_percent = sensor_instance.humidity
            if temperature_celsius is not None and humidity_percent is not None:
                return temperature_celsius, humidity_percent
            else:
                print("Failed to retrieve data from DHT sensor")
                retries += 1
                time.sleep(1)
        except RuntimeError as error:
            # Errors happen fairly often, DHT's are hard to read, just keep going
            print(error.args[0])
            retries += 1
            time.sleep(1)
        except Exception as e:
            sensor_instance.exit()
            raise e
    return None, None


def format_output(temperature, humidity):
    """Formats the temperature and humidity readings for output."""
    return f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%"


def main():
    """Main function to read and display temperature and humidity."""
    dht_sensor = initialize_sensor(DHT_PIN)

    try:
        for _ in range(2):  # Simulate two readings
            temp, hum = read_temperature_humidity(dht_sensor)
            if temp is not None and hum is not None:
                output_string = format_output(temp, hum)
                print(output_string)
            else:
                print("Failed to get reading. Retrying...")
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        dht_sensor.exit()


if __name__ == "__main__":
    main()

