import time
from enum import Enum
from typing import List, Dict, Tuple, Optional, Any

try:
    from gpiozero import PWMOutputDevice,exc
except ImportError:
    print("Error: gpiozero library not found. Please install it using 'pip install gpiozero'.")
    exit(1)


class DutyCycleDirection(Enum):
    """
    Represents the direction of duty cycle change.
    CLOCKWISE: Increases duty cycle from 0 to 1.
    COUNTER0ISE: Decreases duty cycle from 1 to 0.
    """
    CLOCKWISE = "clockwise"
    COUNTERCLOCKWISE = "counterclockwise"


class AmperesFloat(float):
    """Represents a float value with units of amperes."""

    def __new__(cls, value: float) -> "AmperesFloat":
        if not isinstance(value, (int, float)):
            raise TypeError("Value must be a number.")
        return super().__new__(cls, value)

    @property
    def amp(self) -> float:
        """Returns the float value."""
        return float(self)


class Motor:
    """Controls a single DC motor with current protection."""

    def __init__(self, pwm_pin: int, current_limit: AmperesFloat, pwm_frequency: int = 10000) -> None:
        """
        Initializes the motor.

        Args:
            pwm_pin: The GPIO pin connected to the motor's PWM control.
            current_limit: The maximum allowable current in amperes.
            pwm_frequency: The PWM frequency in Hz.
        """
        self.pwm_pin = pwm_pin
        self.current_limit = current_limit
        self._pwm = None  # Initialize _pwm to None
        try:
             self._pwm = PWMOutputDevice(self.pwm_pin, frequency=pwm_frequency)
        except exc.PinFixedPull as e:
            raise RuntimeError(f"GPIO pin {self.pwm_pin} is already in use: {e}")

        self.forward_direction: Optional[DutyCycleDirection] = None
        self._duty_cycle_inversion = False
        self._is_running = False
        self._previous_duty_cycle: Optional[float] = None


    def close(self) -> None:
        """Releases the PWM resource."""
        if self._pwm:
            self._pwm.close()
            self._pwm = None

    def invert(self, invert: bool = None) -> bool:
        """
        Gets or sets the inversion flag.

        Args:
            invert: If provided, sets the inversion flag. Defaults to the current value.

        Returns:
            The current value of the inversion flag.
        """
        if invert is not None:
            if bool(invert) != self._duty_cycle_inversion:  # Avoid unnecessary stops
                self.stop()
                self._duty_cycle_inversion = bool(invert)

        return self._duty_cycle_inversion

    def set_duty_cycle(self, duty_cycle: Optional[float]) -> None:
        """
        Sets the motor's duty cycle, applying inversion if necessary.

        Args:
            duty_cycle: The desired duty cycle (-1.0 to 1.0).
        """
        if duty_cycle is None or duty_cycle == self._previous_duty_cycle:
            return

        if not -1.0 <= duty_cycle <= 1.0:
            raise ValueError("Duty cycle must be between -1.0 and 1.0.")

        try:
            if self.invert():  # Check invert after checking duty cycle range
                duty_cycle *= -1

            if self._pwm:  # Check if _pwm is initialized
                self._pwm.value = duty_cycle
                self._previous_duty_cycle = duty_cycle
        except Exception as e:
            print(f"Error setting duty cycle: {e}")

    def run(self, speed: float, clockwise: Optional[bool] = None) -> None:
        """
        Runs the motor at the specified speed and direction.

        Args:
            speed: A value between -1.0 (full reverse) and 1.0 (full forward).
            clockwise: If provided, forces the motor to spin in the specified direction.
                      If not provided, the direction is determined automatically based on speed.
        """
        if not -1.0 <= speed <= 1.0:
            raise ValueError("Speed must be between -1.0 and 1.0.")

        if clockwise is not None:
            if (speed > 0 and clockwise) or (speed < 0 and not clockwise):
                speed = -speed

        self.set_duty_cycle(speed)
        self._is_running = True

        if speed > 0:
            self.forward_direction = DutyCycleDirection.CLOCKWISE
        elif speed < 0:
            self.forward_direction = DutyCycleDirection.COUNTERCLOCKWISE

    def stop(self) -> None:
        """Stops the motor."""
        self.set_duty_cycle(0)
        self._is_running = False


class MotorDriver:
    """Drives multiple motors with current protection and feedback."""

    MOTOR_PINS: Tuple[int, ...] = (4, 12, 23, 24, 25, 27)  # type: ignore
    MOTORS: Dict[str, Motor] = {}
    CURRENT_LIMITS_AMPS: Tuple[AmperesFloat, ...] = (2.0,) * len(MOTOR_PINS)  # type: ignore
    MAX_SPEED: float = 1.0
    PWM_FREQUENCY: int = 10000
    LOOP_DELAY: float = 2.0 / 1000.0

    def __init__(self) -> None:
        """Initializes the motor driver and creates Motor objects."""
        for i, pin in enumerate(self.MOTOR_PINS):
            try:
                motor = Motor(pin, AmperesFloat(self.CURRENT_LIMITS_AMPS[i]))
                self.MOTORS[f"m{i+1}"] = motor
            except Exception as e:
                print(f"Error initializing motor on pin {pin}: {e}")
                # Handle the error appropriately, e.g., re-raise, skip the pin, or exit.


    def run_motors(self, speeds: Dict[str, float]) -> None:
        """
        Runs the motors at the specified speeds.

        Args:
            speeds: A dictionary mapping motor names ("m1", "m2", etc.) to their desired speeds
                    as values between -1.0 (full reverse) and 1.0 (full forward).
        """

        if not all(-1.0 <= speed <= 1.0 for speed in speeds.values()):
            raise ValueError("All speed values must be between -1.0 and 1.0.")


        try:
            for motor_name, speed in speeds.items():
                motor = self.MOTORS.get(motor_name)
                if motor is None:
                    raise KeyError(f"Invalid motor name: {motor_name}")

                if speed == 0:
                    motor.stop()
                else:
                    motor.run(speed)

        except KeyError as e:
            print(f"Error: {e}")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")


    def think(self) -> None:
        """
        Placeholder method for implementing motor control logic.
        Subclasses can override this method to define specific control algorithms.
        """
        pass

    def run(self) -> None:
        """Runs the main control loop."""
        try:
            while True:
                self.think()  # Call the thinking function
                time.sleep(self.LOOP_DELAY)
        except KeyboardInterrupt:
            print("\nKeyboard interrupt detected. Shutting down...")
        finally:
            for motor in self.MOTORS.values():
                motor.close()


class MotorFeedback(MotorDriver):
    """Implements feedback control for motor speed regulation."""

    def __init__(self) -> None:
        """Initializes the MotorFeedback class."""
        super().__init__()

    def think(self) -> None:
        """Implements the feedback control logic."""
        speeds = {}
        for motor_name in self.MOTORS:
            # Implement your feedback control algorithm here
