    try:
        if 0 <= actuator_index < len(valve_pins):
            pin = valve_pins[actuator_index]
            if desired_state == "ON":
                GPIO.output(pin, GPIO.HIGH)
                print(f"Actuator {actuator_index} (Pin {pin}) set to ON")
            elif desired_state == "OFF":
