from ina219 import INA219, DeviceRangeError

# Configuration constants
INA_ADDR = 0x17  # I2C address of the INA219 sensor
SLEEP_INTERVAL = 2  # Time between readings in seconds


def initialize_ina(address):
    """Initialize the INA219 sensor."""
    try:
        ina = INA219(0.1, busnum=1, address=address)
        ina.configure()
        return ina
    except Exception as e:
        print(f"Error initializing INA219: {e}")
        return None


def read_sensor_data(sensor):
    """Read voltage, current, and power from the sensor."""
    try:
        voltage = sensor.voltage()
        current = sensor.current()
        power = sensor.power()
        return voltage, current, power
    except DeviceRangeError:
        print("Current out of range.")
        return None, None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None


def display_results(voltage, current, power):
    """Print the sensor readings to the console."""
    if all(val is not None for val in [voltage, current, power]):
        print(f"Voltage: {voltage:.3f} V")
        print(f"Current: {current:.3f} mA")
        print(f"Power: {power:.3f} mW")


def main():
    """Main function to continuously monitor solar panel voltage and current."""
    sensor = initialize_ina(INA_ADDR)

    if sensor is None:
        exit(1)  # Exit with error code if initialization fails

    try:
        while True:
            voltage, current, power = read_sensor_data(sensor)
            display_results(voltage, current, power)
            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        # No specific cleanup needed for smbus2 or ina219 in this context,
        # but included for potential future expansion.
        pass


if __name__ == "__main__":
