def configure_adc():
    """Set up the SPI interface and chip select pin."""
    spi_bus = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    chip_select = digitalio.DigitalInOut(board.CE0)
    adc_device = None
    try:
        adc_device = Adafruit_MCP3008.Adafruit_MCP3008(spi_bus, chip_select)
    except Exception as e:
        print("ADC setup failed:", e)
    return adc_device

# Read a raw value from the specified ADC channel
def read_pot_value(adc_device, channel_index):
    """Read a 10-bit value from one of the MCP3008 channels."""
    if not adc_device:
        return None
    try:
        raw_value = adc_device.read_channel(channel_index)
        # Clamp the value into the valid 0..1023 range
        return max(0, min(raw_value, 1023))
    except Exception as e:
        print("Read error:", e)
        return None

if __name__ == "__main__":
