# Parking sensor simulation using HC-SR04 ultrasonic distance sensor.
# Reads distance from gpiozero and prints vehicle proximity states.

import time
from gpiozero import DistanceSensor

def read_distance(sensor):
    """Reads distance in meters from the ultrasonic sensor."""
    try:
        return sensor.distance * 100  # Convert to centimeters
    except Exception as e:
        print(f"Error reading sensor: {e}")
        return None

def interpret_state(distance):
    """Interprets the distance and returns a parking state."""
    if distance is None or distance > 50:
        return "empty"
    elif 30 <= distance <= 50:
        return "medium"
    else:
        return "occupied"

if __name__ == "__main__":
    # Initialize the HC-SR04 sensor connected to GPIO pins 17 and 18.
    try:
        sensor = DistanceSensor(echo=18, trigger=17)
    except Exception as e:
        print(f"Failed to initialize sensor: {e}")
        exit(1)

    try:
        for _ in range(10):  # Simulate 10 readings
            distance_cm = read_distance(sensor)
            if distance_cm is not None:
                state = interpret_state(distance_cm)
                print(f"State: {state}, Distance: {distance_cm:.2f} cm")
            time.sleep(0.1)  # Simulate sampling rate of 10 Hz
    except KeyboardInterrupt:
        print("\nProgram interrupted.")
    finally:
        sensor.close()  # Release GPIO resources
        print("GPIO resources released.")

