# proximity_sensor_demo.py
# A simple demo of proximity sensors on Raspberry Pi using gpiozero.
import time
from gpiozero import DistanceSensor

# Define sensor pins using BCM numbering
SENSOR_PINS = {
    "sensor_1": {"trigger": 5, "echo": 6},
    "sensor_2": {"trigger": 17, "echo": 18},
    "sensor_3": {"trigger": 22, "echo": 23},
    "sensor_4": {"trigger": 24, "echo": 27}
}

def read_sensors(sensor_objects):
    """Reads distance from each sensor and returns the results."""
    distances = {}
    for name, sensor in sensor_objects.items():
        try:
            # Measure distance in centimeters
            distance = sensor.distance * 100
            distances[name] = round(distance, 2)
        except Exception as e:
            print(f"Error reading {name}: {e}")
            distances[name] = None
    return distances

def report_state(distances):
    """Prints the current state of each sensor."""
    print("Current Proximity Sensor State:")
    for name, distance in distances.items():
        status = f"{name} - Distance: {distance} cm" if distance is not None else f"{name} - No response"
        print(status)

if __name__ == "__main__":
    # Initialize sensor objects
    sensors = {}
    try:
        for name, pins in SENSOR_PINS.items():
            # Create DistanceSensor object
            sensors[name] = DistanceSensor(echo=pins["echo"], trigger=pins["trigger"])

        # Read sensor values
        sensor_data = read_sensors(sensors)

        # Print the current state
        report_state(sensor_data)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Cleanly close the sensor connections
        for sensor in sensors.values():
            sensor.close()
        print("GPIO resources released.")

