import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Configuration constants
I2C_ADDRESS = 0x48  # Default I2C address of the ADS1115
SAMPLE_INTERVAL_SECONDS = 0.1  # Time between sensor readings


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_adc(i2c_bus):
    """Initialize the ADS1115 ADC."""
    try:
        return ADS.ADS1115(i2c_bus, address=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing ADS1115: {e}")
        return None


def create_analog_input_channel(adc_device, channel_number=0):
    """Create an analog input channel on the specified ADC channel number."""
    try:
        return AnalogIn(adc_device, channel_number)
    except Exception as e:
        print(f"Error creating analog input channel: {e}")
        return None


def read_sensor_value(channel_object):
    """Read the raw value from the specified analog input channel."""
    try:
        return channel_object.value
    except Exception as e:
        print(f"Error reading sensor value: {e}")
        return None


def validate_reading(reading_value):
    """Validate that the reading is within a reasonable range."""
    return 0 <= reading_value <= 65535


def process_reading(reading_value):
    """Print the sensor reading to the console."""
    print(f"Sensor Reading: {reading_value}")


def main():
    """Main function to continuously sample and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return 1  # Indicate initialization failure

    adc_device = initialize_adc(i2c_bus)
    if adc_device is None:
        return 1

    sensor_channel = create_analog_input_channel(adc_device)
    if sensor_channel is None:
        return 1

    try:
        while True:
            raw_value = read_sensor_value(sensor_channel)

            if raw_value is not None and validate_reading(raw_value):
                process_reading(raw_value)

            time.sleep(SAMPLE_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        # No explicit cleanup needed for these libraries, but included for completeness.
        if i2c_bus:
            i2c_bus.deinit()


if __name__ == "__main__":
    exit_code = main()
    if exit_code != 0:
        import sys
        sys.exit(exit_code)

import time
import board
import adafruit_dht

# Configuration constants
DHT_PIN = board.D4
READ_INTERVAL_SECONDS = 5
CYCLE_COUNT = 10

def initialize_sensor(pin):
    """Initializes the DHT sensor."""
    return adafruit_dht.DHT22(pin)

def read_sensor_data(sensor_instance):
    """Reads temperature and humidity from the DHT sensor."""
    try:
        temperature_c = sensor_instance.temperature
        humidity_percent = sensor_instance.humidity
        return temperature_c, humidity_percent
    except RuntimeError as error:
        print(f"Sensor reading error: {error}")
        return None, None

def format_output(temperature, humidity):
    """Formats the sensor data into a JSON-like string."""
    if temperature is not None and humidity is not None:
        return f'{{"temperature": {temperature:.1f}, "humidity": {humidity:.1f}}}'
    else:
        return '{"state": "failure"}'

def main():
    """Main function to read and report sensor data."""
    sensor = initialize_sensor(DHT_PIN)

    try:
        for _ in range(CYCLE_COUNT):
            temp, hum = read_sensor_data(sensor)
            output = format_output(temp, hum)
            print(output)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # No specific cleanup needed for adafruit_dht, but good practice to include
        print("Exiting...")

if __name__ == "__main__":
    main()

import time
from gpiozero import PWMOutputDevice

# Define GPIO pins for PWM control (BCM numbering)
fan_pins = [14, 15, 18]

# Create PWM objects for each fan
fans = []
for pin in fan_pins:
    fans.append(PWMOutputDevice(pin))

try:
    # Main loop to continuously adjust fan speed
    while True:
        # Get user input for desired fan speeds (0.0 to 1.0)
        speeds = []
        try:
            for i in range(len(fan_pins)):
                speed_str = input(f"Fan {i+1} Speed (0.0 - 1.0): ")
                speed = float(speed_str)
                if 0.0 <= speed <= 1.0:
                    speeds.append(speed)
                else:
                    print("Invalid input. Using default (0.0).")
                    speeds.append(0.0)
        except ValueError:
            print("Invalid input. Using default speeds.")
            speeds = [0.0] * len(fan_pins)

        # Set fan speeds
        for i, fan in enumerate(fans):
            if i < len(speeds):
                fan.value = speeds[i]
            else:
                fan.value = 0.0  # Turn off if no speed is provided

        # Print current fan states
        print("-" * 10)
        for i, fan in enumerate(fans):
            print(f"Fan {i+1}: {fan.value:.2f}")
        print("-" * 10)

        # Wait before next adjustment
        time.sleep(0.1)

except KeyboardInterrupt:
    print("\nExiting...")

finally:
    # Ensure fans are turned off and resources are released
    for fan in fans:
        fan.close()
    print("Fans stopped.")

import time
import board
import adafruit_dht

# Configuration constants
DHT_PIN = board.D4
READ_INTERVAL_SECONDS = 10
NUM_READINGS = 3


def initialize_sensor(pin):
    """Initializes the DHT22 sensor."""
    return adafruit_dht.DHT22(pin)


def read_sensor_data(sensor_instance):
    """Reads temperature and humidity from the DHT22 sensor."""
    try:
        temperature_c = sensor_instance.temperature
        humidity_percent = sensor_instance.humidity
        return temperature_c, humidity_percent
    except RuntimeError as error:
        print(f"Sensor read error: {error}")
        return None, None


def validate_data(temperature, humidity):
    """Validates that temperature and humidity readings are within reasonable bounds."""
    if temperature is not None and (-20 <= temperature <= 60):
        if humidity is not None and (0 <= humidity <= 100):
            return True
    return False


def format_output(temperature, humidity):
    """Formats the temperature and humidity data into a string."""
    return f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%"


def main():
    """Main function to read and display temperature and humidity data."""
    sensor = initialize_sensor(DHT_PIN)

    try:
        for _ in range(NUM_READINGS):
            temperature, humidity = read_sensor_data(sensor)

            if validate_data(temperature, humidity):
                output_string = format_output(temperature, humidity)
                print(output_string)
            else:
                print("Invalid sensor data. Check readings.")

            time.sleep(READ_INTERVAL_SECONDS)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return 1  # Indicate failure
    finally:
        print("Program finished.")


if __name__ == "__main__":
    exit_code = main()
    if exit_code:
        import sys
        sys.exit(exit_code)

